import java.util.function.Supplier;
import lombok.val;

public class ValGenerics {
	interface ThrowableSupplier<T> {
		T apply() throws Throwable;
	}

	public static <T> T assumeNoThrow(ThrowableSupplier<T> procedure) {
		try {
			return procedure.apply();
		} catch (Throwable e) {
			throw new RuntimeException(e);
		}
	}

	public void test() {
		val cipher = assumeNoThrow(() -> {
			val x = new StringBuilder("a");
			x.append("b");
			return x;
		});
		val encrypted = cipher.toString();
		val decrypted = encrypted.toString();
		System.out.println(decrypted);
	}
}
